`[Console]::OutputEncoding = [System.Text.Encoding]::UTF8; $OutputEncoding = [System.Text.Encoding]::UTF8; chcp 65001 | Out-Null
$skip = @('.git','.obsidian','.claude','.buildian','copilot','Attachments','📅 日常工作','💼 工作专项','📚 专业领域','💡 个人思考','🤖 AI 学习&实操','📝 日常记录')
$root = Get-Location
Get-ChildItem -Force | Where-Object { $_.Name -notin $skip } | ForEach-Object {
  if ($_.PSIsContainer) {
    Get-ChildItem -LiteralPath $_.FullName -Recurse -Force -File -ErrorAction SilentlyContinue | ForEach-Object {
      $_.FullName.Substring($root.Path.Length + 1)
    }
  } else {
    $_.Name
  }
}`

