`[Console]::OutputEncoding = [System.Text.Encoding]::UTF8
$OutputEncoding = [System.Text.Encoding]::UTF8
chcp 65001 | Out-Null
$ErrorActionPreference = 'Stop'

# fix 三板斧 misclassified to 日常记录
$src = Get-ChildItem -LiteralPath "📝 日常记录" -File | Where-Object { $_.Name -like '*三板斧*' }
if ($src) {
  $dst = Join-Path "🤖 AI 学习&实操" $src.Name
  if (-not (Test-Path -LiteralPath $dst)) {
    Move-Item -LiteralPath $src.FullName -Destination $dst
    Write-Host "FIXED: $($src.Name) -> AI 学习&实操"
  }
}

# remove empty PARA dirs
$toRemove = @(
  "00 Inbox",
  "10 Notes",
  "20 Projects",
  "30 Areas",
  "90 Archive"
)
foreach ($d in $toRemove) {
  if (Test-Path -LiteralPath $d) {
    $left = Get-ChildItem -LiteralPath $d -Recurse -Force -ErrorAction SilentlyContinue
    if ($null -eq $left -or @($left).Count -eq 0) {
      Remove-Item -LiteralPath $d -Recurse -Force
      Write-Host "REMOVED empty: $d"
    } else {
      Write-Host "KEEP (not empty): $d"
      $left | ForEach-Object { Write-Host "  leftover: $($_.FullName.Replace((Get-Location).Path+'\',''))" }
    }
  } else {
    Write-Host "already gone: $d"
  }
}

Write-Host "\`n=== Final tree (content) ==="
$cores = @("📅 日常工作","💼 工作专项","📚 专业领域","💡 个人思考","🤖 AI 学习&实操","📝 日常记录")
foreach ($c in $cores) {
  Write-Host "\`n### $c"
  Get-ChildItem -LiteralPath $c -Recurse -Force -ErrorAction SilentlyContinue | ForEach-Object {
    $rel = $_.FullName.Substring((Resolve-Path -LiteralPath $c).Path.Length + 1)
    if ($_.PSIsContainer) { Write-Host "  DIR  $rel" } else { Write-Host "  FILE $rel" }
  }
}

Write-Host "\`n=== Root leftover content ==="
Get-ChildItem -Force | Where-Object {
  $_.Name -notin @('.git','.obsidian','.claude','.buildian','copilot','Attachments','📅 日常工作','💼 工作专项','📚 专业领域','💡 个人思考','🤖 AI 学习&实操','📝 日常记录','.gitignore')
} | ForEach-Object { Write-Host $_.Name }`

