`[Console]::OutputEncoding = [System.Text.Encoding]::UTF8; $OutputEncoding = [System.Text.Encoding]::UTF8
function DirSize($p) {
  if (Test-Path -LiteralPath $p) {
    $b = (Get-ChildItem -LiteralPath $p -Recurse -File -Force -ErrorAction SilentlyContinue | Measure-Object -Property Length -Sum).Sum
    "{0:N1} MB  {1}" -f ($b/1MB), $p
  }
}
DirSize '.claude'
DirSize '.buildian'
DirSize '.obsidian/plugins'
DirSize 'copilot'
@('📅 日常工作','💼 工作专项','📚 专业领域','💡 个人思考','🤖 AI 学习&实操','📝 日常记录') | ForEach-Object { DirSize $_ }
Write-Host "==== repo privacy ==="
gh repo view lobokiol/lobo-review --json visibility,url 2>&1`

